package android.graphics;public class RectF {public float left,top,right,bottom;public RectF(){}public RectF(RectF r){left=r.left;top=r.top;right=r.right;bottom=r.bottom;}public RectF(float l,float t,float r,float b){left=l;top=t;right=r;bottom=b;}public boolean equals(Object o){if(!(o instanceof RectF))return false;RectF r=(RectF)o;return left==r.left&&top==r.top&&right==r.right&&bottom==r.bottom;}}